<?php
if(PHP_SAPI!=='cli' || !isset($pdo,$name) || !preg_match('/^bulkbites_baseline_[a-f0-9]{12}$/D',$name)) { exit(1); }
$GLOBALS['BB_CONFIG']['app']['demo_payments_enabled']=true;
$GLOBALS['BB_CONFIG']['paymongo']=[];
$pdo->exec('UPDATE store_settings SET ordering_status="OPEN",use_hours=0,cooldown_seconds=0,max_active_orders=1000,max_item_qty=1000,max_order_qty=1000');
$pdo->prepare('INSERT INTO products(category_id,name,price) VALUES (?,"Simulator test product",15.50)')->execute([$category]);$demoProduct=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO inventory(product_id,quantity_available) VALUES (?,100)')->execute([$demoProduct]);
$newDemo=static function() use($customer,$demoProduct): array { $_SESSION['cart']=[$demoProduct=>2];return place_order($customer,'DEMO','Simulator fixture','Demo customer'); };
$demoStock=static fn()=>(int)$pdo->query('SELECT quantity_available FROM inventory WHERE product_id='.$demoProduct)->fetchColumn();
$demo=$newDemo();baseline_check($demo['ok'],'Demo checkout works without PayMongo credentials');$demoId=(int)$demo['order_id'];
$demoRow=static fn()=>$pdo->query('SELECT * FROM orders WHERE id='.$demoId)->fetch();
baseline_check($demoRow()['payment_status']==='PENDING' && (int)$demoRow()['payment_is_test']===1,'Demo order is clearly marked simulated before payment');
baseline_check(!advance_order_status($demoId,'ACCEPTED',$manager)['ok'],'Unpaid demo order cannot be accepted');
baseline_check(!simulate_order_payment($demoId,$manager,'success')['ok'],'Another account cannot simulate payment for the customer');
baseline_check(!simulate_order_payment($demoId,$customer,'unknown')['ok'],'Invalid demo outcome cannot change payment');
$events=static fn()=>(int)$pdo->query('SELECT COUNT(*) FROM payment_events WHERE order_id='.$demoId)->fetchColumn();
baseline_check(!simulate_order_payment($demoId,$customer,'failed')['ok'] && $events()===0 && $demoRow()['payment_status']==='PENDING','Failed demo attempt stays unpaid without a payment event');
baseline_check(!simulate_order_payment($demoId,$customer,'cancelled')['ok'] && $events()===0 && $demoStock()===98 && $demoRow()['status']==='NEW','Cancelled payment attempt stays unpaid and keeps its timed reservation');
$beforeCollections=payment_collection_summary(date('Y-m-d'),date('Y-m-d'));
baseline_check(simulate_order_payment($demoId,$customer,'success')['ok'] && $demoRow()['payment_status']==='PAID','Successful simulation confirms the demo payment');
$event=$pdo->query('SELECT * FROM payment_events WHERE order_id='.$demoId)->fetch();
baseline_check((int)$event['is_test']===1 && (float)$event['amount']===31.0 && $demoStock()===98,'Demo payment uses saved total and does not deduct stock again');
baseline_check(simulate_order_payment($demoId,$customer,'success')['ok'] && $events()===1,'Repeated simulator success is idempotent');
$afterCollections=payment_collection_summary(date('Y-m-d'),date('Y-m-d'));
baseline_check($beforeCollections['collected']===$afterCollections['collected'] && $beforeCollections['unpaid']===$afterCollections['unpaid'],'Demo totals stay outside real collections and unpaid cashflow');
baseline_check(advance_order_status($demoId,'ACCEPTED',$manager)['ok'],'Paid demo order can be accepted by staff');
$_SESSION['cart']=[$demoProduct=>1];$cashDemo=place_order($customer,'CASH','Cash isolation');
baseline_check(!simulate_order_payment((int)$cashDemo['order_id'],$customer,'success')['ok'],'Simulator cannot mark a cash order paid');
$_SESSION['cart']=[$demoProduct=>1];$realTest=place_order($customer,'GCASH','Provider isolation');
baseline_check(!simulate_order_payment((int)$realTest['order_id'],$customer,'success')['ok'],'Simulator cannot confirm a provider checkout order');
$lateDemo=$newDemo();$lateId=(int)$lateDemo['order_id'];$beforeLateStock=$demoStock();
$pdo->exec('UPDATE orders SET reservation_expires_at=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE id='.$lateId);
baseline_check(!simulate_order_payment($lateId,$customer,'success')['ok'] && $demoStock()===$beforeLateStock+2,'Expired demo payment releases stock without marking payment paid');
baseline_check(!simulate_order_payment($lateId,$customer,'success')['ok'] && $demoStock()===$beforeLateStock+2,'Repeated expired demo action cannot return stock twice');
$cancelDemo=$newDemo();$cancelId=(int)$cancelDemo['order_id'];cancel_customer_order($cancelId,$customer);
baseline_check(!simulate_order_payment($cancelId,$customer,'success')['ok'],'Cancelled order cannot be revived by a demo success');
$GLOBALS['BB_CONFIG']['app']['demo_payments_enabled']=false;
baseline_check(!$newDemo()['ok'] && !simulate_order_payment($demoId,$customer,'success')['ok'],'Disabling simulation blocks new orders and simulator actions');
$GLOBALS['BB_CONFIG']['app']['demo_payments_enabled']=true;
$raceDemo=$newDemo();$raceId=(int)$raceDemo['order_id'];
$race=baseline_parallel([['demo',(string)$raceId,(string)$customer],['demo',(string)$raceId,(string)$customer]]);
baseline_check($race[0]['ok'] && $race[1]['ok'] && (int)$pdo->query('SELECT COUNT(*) FROM payment_events WHERE order_id='.$raceId)->fetchColumn()===1,'Concurrent success requests record exactly one demo payment');
$raceCancel=$newDemo();$raceCancelId=(int)$raceCancel['order_id'];$stockBeforeCancel=$demoStock();
$race=baseline_parallel([['demo',(string)$raceCancelId,(string)$customer],['cancel',(string)$raceCancelId,(string)$customer]]);
$state=$pdo->query('SELECT * FROM orders WHERE id='.$raceCancelId)->fetch();
baseline_check($state['status']==='CANCELLED' && $demoStock()===$stockBeforeCancel+2 && in_array($state['payment_status'],['PENDING','REFUND_REQUIRED'],true),'Simulation and order cancellation race returns stock once with safe refund state');
$content=receipt_email_content(['pickup_name'=>'Demo customer','pickup_location'=>'Demo counter','issued_at'=>date('Y-m-d H:i:s'),'receipt_number'=>'RC-DEMO','order_number'=>'BB-DEMO','total'=>'31.00','payment_method'=>'DEMO','payment_is_test'=>1],[]);
baseline_check(str_contains($content['text'],'DEMO PAYMENT') && str_contains($content['html'],'DEMO PAYMENT') && str_contains($content['html'],'Demo total'),'Receipt email clearly identifies simulated payment in HTML and text');
